@six.add_metaclass(NotifyingClassCreator)
class LteUe:
    """LTE Ue general object"""

    def __init__(self, name, configuration=None):
        """
        Definition of Abstract UE API
        :param name: name of UE to be stored inside UE object
        :param configuration: anything required to instantiate specific UE
        :return: None
        :raises: :py:class:`ute_ue.exceptions.ProhibitedInstanceError`: if trying to instantiate base class
        """
        self.name = name
        self.ue_id = None
        self.phone_number = None
        self._configuration = configuration if configuration else {}
        if self.__class__.__name__ == 'LteUe':
            raise ProhibitedInstanceError("you can't create instance of UE base class, use derived ones")
        # This logger should be used to log UE specific events
        # TODO: rename after decision
        self.ue_logger_name = f'ute_ue.ue.{self.name}'
        self._configuration['ue_logger_name'] = self.ue_logger_name  # where it is used: ue_logger_name
        self.logger = logger_wrapper.create_logger(self.ue_logger_name, f'UE_{self.name}.log')
        self.bearers = []
        self.voice_calls = {}
        self.alias = ""
        self.reserved = False
        self.rpc_client = None
        self.ue_pc = None  # Placeholder for rpc_client element used in some plugins
        self._python_api = False
        self.diagnostic_data = None
        self.data_transfers = {}
        self._sub_access = None
        self.allow_kw_logs = self._configuration.get('allow_kw_logs', True)

    def __str__(self):
        return "{}({})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '')

    def __repr__(self):
        return "{}({}, at {})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '', hex(id(self)))

    @property
    def access(self):
        """
        Placeholder for Ue specific access
        :return: str: UE type name
        """
        sub_access = getattr(self, '_sub_access', None)
        if sub_access and isinstance(sub_access, str):
            ue_type = sub_access
        else:
            ue_type = self.__class__.__name__
        return ue_type.replace('Ue', '').lower()

    def gracefully_shutdown(self):
        """

        """
        self.reserved = False
        try:
            self.shutdown()
        except Exception as exc:
            self.logger.warning(f"Release UE={self.ue_id} ({self.alias}), failed on:\n{exc}")

    def shutdown(self):
        """
        Placeholder for Ue specific cleanups
        :return:
        """
        ...

    def keep_reservation(self):
        """
        Placeholder for Ue specific keep reservation
        :return:
        """
        self.rpc_client.keep_reservation(ue_id=self.ue_id)

