    def connect_additional_pdn(self, pdn):
        """
        A way to establish additional default bearer.

        :param pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If connecting given PDN failed

        PDN is identified by APN. That builds basic structure of configuration:
        we map from 'PDN logical name' (used by scripts) to APN that identifies PDN.
        That way same 'PDN logical name' may work on different configurations (for test portability).

        Exact configuration depends on type of UEs-pool that has provided UE referred by ue_alias.
        UEs-pool may add it's own keys (besides apn) required to establish new PDN connection.
        Following example is just to show that testers may use meaningful names for PDN,
        names that have domain meaning inside tests (like "default PDN", "emergency PDN" below)

        +---------------------------------------------------------+
        |     Example  configuration                              |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   PDN:                                                  |
        |       default:                                          |
        |           apn: internet                                 |
        |           MediaTekUePool:                               |
        |               pdp_type: IPV4V6                          |
        |           IphyUePool:                                   |
        |               pdn_id: 1                                 |
        |       mms:                                              |
        |           apn: mms.t-mobile                             |
        |           MediaTekUePool:                               |
        |               pdp_type: IPV4V6                          |
        |           IphyUePool:                                   |
        |               pdn_id: 2                                 |
        |       emergency:                                        |
        |           apn: t-mobile.sos                             |
        |           MediaTekUePool:                               |
        |               pdp_type: Ethernet                        |
        |           IphyUePool:                                   |
        |               pdn_id: 3                                 |
        |                                                         |
        +---------------------------------------------------------+
        """
        raise NotImplementedError()

